#!/usr/bin/env node
/**
 * Builds `sql/grixchat_full_setup.sql` by concatenating the numbered migrations
 * in order, so a new fork can paste ONE file into the Supabase SQL editor.
 *
 * The numbered files stay the source of truth. Run:
 *     npm run sql:bundle            # regenerate
 *     npm run sql:bundle -- --check # fail if the bundle is stale (CI + tests)
 */
import {readFileSync, writeFileSync, existsSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname, join} from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const sqlDir = join(here, '..', 'sql');
const OUT = join(sqlDir, 'grixchat_full_setup.sql');

const FILES = [
  '01_core_schema.sql',
  '02_posts_and_interactions_schema.sql',
  '03_support_tickets_schema.sql',
  '04_triggers_functions_and_rpc.sql',
  '05_advanced_optimizations_and_realtime.sql',
  '06_storage_configurations.sql',
  '07_chat_time_scheduling_migration.sql',
  '08_stories_expiration_and_views.sql',
  '09_egress_optimizations.sql',
];

const rule = '-- ' + '═'.repeat(74);

function banner(name, index, total) {
  return `${rule}
-- PART ${index}/${total} — sql/${name}
-- (generated from the file of that name; edit THAT file, then re-run
--  "npm run sql:bundle" — do not edit this bundle by hand)
${rule}
`;
}

export function buildBundle() {
  const parts = [
    `${rule}
-- GRIXCHAT — COMPLETE SUPABASE SETUP (generated, do not edit by hand)
${rule}
-- One paste for a brand-new Supabase project:
--   Supabase Dashboard -> SQL Editor -> New query -> paste ALL of this -> RUN.
--
-- Safe to run again later, on the same project, at any time:
--   * nothing is dropped or truncated
--   * tables/columns/indexes/constraints are created only when missing
--   * policies and functions are re-created, so updated definitions apply
--   * existing rows are never modified
--
-- Generated by: npm run sql:bundle   (source: sql/01_*.sql … sql/09_*.sql)
-- Read first:    sql/00_master_instructions.md
${rule}
`,
  ];

  FILES.forEach((name, i) => {
    const path = join(sqlDir, name);
    if (!existsSync(path)) throw new Error(`missing migration: ${name}`);
    parts.push('\n' + banner(name, i + 1, FILES.length) + '\n' + readFileSync(path, 'utf8').trimEnd() + '\n');
  });

  parts.push(`\n${rule}
-- DONE. Verify with the checklist in sql/00_master_instructions.md
${rule}
`);
  return parts.join('\n');
}

export function readBundle() {
  return existsSync(OUT) ? readFileSync(OUT, 'utf8') : null;
}

const isCheck = process.argv.includes('--check');
const expected = buildBundle();
const current = readBundle();

if (isCheck) {
  if (current !== expected) {
    console.error('sql/grixchat_full_setup.sql is STALE — run: npm run sql:bundle');
    process.exit(1);
  }
  console.log('sql bundle is up to date');
} else {
  writeFileSync(OUT, expected);
  console.log(`wrote sql/grixchat_full_setup.sql (${expected.split('\n').length} lines)`);
}
